/**
 * Lab metadata for the /docs/labs landing page.
 *
 * WHY THIS IS HAND-MAINTAINED rather than read out of the lab frontmatter:
 * website/docs is generated by scripts/sync-docs.mjs and gitignored, and the
 * lab markdown is canonical in curriculum/ where it is also read on GitHub.
 * Adding phase names and one-line taglines to that markdown would put landing
 * page copy in the middle of the labs. So the labs own their content and this
 * file owns how the path through them is presented, the same split that
 * src/data/lab-videos.json already uses for YouTube ids.
 *
 * `minutes` and `requires` mirror the "Time / Prerequisites" line at the top
 * of each lab. If you change one, change the other.
 */

export type Lab = {
  /** Position in the sequence, and the number rendered on the rail. */
  n: number;
  /** Doc id under docs/labs, without the folder. */
  slug: string;
  /** Title without the "Lab N — " prefix; the rail carries the number. */
  title: string;
  /** One sentence on what the lab is actually for. Not a summary. */
  tagline: string;
  /** Minutes, from the lab's own Time line. */
  minutes: number;
  /** Lab numbers this one builds on. */
  requires: number[];
  /** A prerequisite that is not a lab, e.g. "Setup complete". */
  requiresText?: string;
  /** The route or API surface the lab introduces. Rendered as code. */
  tag: string;
  /** Labs a learner can do without an Anthropic key. */
  noKey?: boolean;
};

export type Phase = {
  label: string;
  blurb: string;
  labs: Lab[];
};

