/** Flat sequence, for lookups by number. */
export const ALL_LABS: Lab[] = LAB_PATH.flatMap((phase) => phase.labs);

export function labHref(lab: Lab): string {
  return `/docs/labs/${lab.slug}`;
}

/** Total run time across every lab, as "7h 20m". */
export function totalTime(): string {
  const total = ALL_LABS.reduce((sum, lab) => sum + lab.minutes, 0);
  const hours = Math.floor(total / 60);
  const minutes = total % 60;
  return minutes === 0 ? `${hours}h` : `${hours}h ${minutes}m`;
}
